import requests, xml.etree.ElementTree as ET
terms=['("perfusion index" AND glucose AND capillary)','(hypoperfusion AND capillary AND venous AND glucose)','("poor peripheral perfusion" AND glucose)','(shock AND capillary AND venous AND glucose)','(vasoconstriction AND capillary glucose)']
for term in terms:
    url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
    r=requests.get(url,params={'db':'pubmed','term':term,'retmax':20,'retmode':'json'},timeout=20)
    ids=r.json()['esearchresult']['idlist']
    print('\nQUERY',term,'N',len(ids),ids[:10])
    if ids:
        x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids[:10]),'retmode':'json'},timeout=20).json()['result']
        for i in ids[:10]: print(i, x[i].get('title',''))
